class Solution:
    def maximumOddBinaryNumber(self, s: str) -> str:
        ones = s.count('1')
        zeros = len(s) - ones
        return '1' * (ones - 1) + '0' * zeros + '1'

class Solution {
public:
    string maximumOddBinaryNumber(string s) {
        int ones = 0, n = s.size();
        for (char c : s) if (c == '1') ones++;
        int zeros = n - ones;
        return string(ones - 1, '1') + string(zeros, '0') + "1";
    }
};

class Solution {
    public String maximumOddBinaryNumber(String s) {
        int ones = 0, n = s.length();
        for (char c : s.toCharArray()) if (c == '1') ones++;
        int zeros = n - ones;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ones - 1; i++) sb.append('1');
        for (int i = 0; i < zeros; i++) sb.append('0');
        sb.append('1');
        return sb.toString();
    }
}

/**
 * @param {string} s
 * @return {string}
 */
var maximumOddBinaryNumber = function(s) {
    let ones = 0;
    for (const c of s) if (c === '1') ones++;
    const zeros = s.length - ones;
    return '1'.repeat(ones - 1) + '0'.repeat(zeros) + '1';
};
